import type { CollegePreview } from "@/lib/colleges";

/**
 * Client-side loaders for the public/data/*.json assets generated by
 * scripts/merge-global-dataset.ts. These exist so islands that need the
 * FULL worldwide dataset (the homepage map/search, and teleport from any
 * page) fetch one small shared static asset instead of having it
 * embedded in every page's HTML — see that script's file header for why.
 * Each loader memoizes its in-flight/completed fetch per page load, so
 * multiple islands requesting the same data only cause one network
 * request.
 */

let previewPromise: Promise<CollegePreview[]> | null = null;

export function loadInstitutionPreviews(): Promise<CollegePreview[]> {
  if (!previewPromise) {
    previewPromise = fetch("/data/institutions-preview.json")
      .then((res) => {
        if (!res.ok) throw new Error(`institutions-preview.json: ${res.status}`);
        return res.json() as Promise<CollegePreview[]>;
      })
      .catch((err) => {
        previewPromise = null; // allow a retry on the next call
        throw err;
      });
  }
  return previewPromise;
}

let slugsPromise: Promise<string[]> | null = null;

export function loadAllSlugs(): Promise<string[]> {
  if (!slugsPromise) {
    slugsPromise = fetch("/data/slugs.json")
      .then((res) => {
        if (!res.ok) throw new Error(`slugs.json: ${res.status}`);
        return res.json() as Promise<string[]>;
      })
      .catch((err) => {
        slugsPromise = null;
        throw err;
      });
  }
  return slugsPromise;
}
